/** Exact GraphQL typenames, keyed by frontend family name. */
export const SectionTypename = {
  Hero: "HeroBanner",

  /* foundry:wiring:typenames:start */
  Sliders: "Sliders",
  Ctas: "Ctas",
  Banners: "Banners",
  ContentSideBySide: "ContentSideBySide",
  FeatureCards: "FeatureCards",
  ContentCards: "ContentCards",
  Accordions: "Accordions",
  TabsAndPills: "TabsAndPills",
  ContentLists: "ContentLists",
  /* foundry:wiring:typenames:end */
} as const;

/** Exact CMS values. Preserve spaces and capitalization in real projects. */
export const HeroFrontendComponent = {
  HeroWithBanner: "heroWithBanner",
  HeroWithCTA: "heroWithCTA",
} as const;

/**
 * Exact CMS values of `flexiblePage.headerVarient` — note the field's spelling
 * in the model. These select the header's colourway per page; the styling for
 * each lives in components/common/header.
 *
 * Each value names what it does: whether the bar carries the dark overlay, then
 * the ink, then the icon pills. The field still allows the earlier colour-named
 * set (Blue, Light Blue, Black, Yellow, Orange, Dark Overlay on Image) and still
 * defaults to one of them — a page on any of those falls back to the default
 * below until the backend narrows the validation and moves the default.
 */
export const HeaderVariant = {
  OverlayLightTextBlueIcons: "Overlay - Light Text - Blue Icons",
  NoOverlayDarkTextLightBlueIcons: "No Overlay - Dark Text - Light Blue Icons",
  NoOverlayDarkTextBlueIcons: "No Overlay - Dark Text - Blue Icons",
  NoOverlayLightTextBlueIcons: "No Overlay - Light Text - Blue Icons",
} as const;

/** The overlay treatment, which is what the retired default rendered. */
export const DEFAULT_HEADER_VARIANT = HeaderVariant.OverlayLightTextBlueIcons;
/* foundry:wiring:variants:start */
export const SlidersFrontendComponent = {
  LogoSlider: "Logo Slider",
} as const;
export const CtasFrontendComponent = {
  Cta: "CTA",
  IndustryLinks: "Industry Links",
} as const;
export const BannersFrontendComponent = {
  BannerWithImage: "Banner with Image",
  BannerWithoutImage: "Banner without Image",
  HomepageBanner: "Homepage Banner",
} as const;
export const ContentSideBySideFrontendComponent = {
  BulletsCTAImage: "Bullets + CTA + Image",
  IntroDeck: "Intro Deck",
  FeatureListImage: "Feature List + Image",
  MediaTextCTA: "Media + Text + CTA",
} as const;
export const FeatureCardsFrontendComponent = {
  FeatureCardOptionalLink: "Feature Card + Optional Link",
  FullWidthFeatureList: "Full width feature list",
  FeatureCard: "Feature Card",
} as const;
export const ContentCardsFrontendComponent = {
  FeatureImageDetailLinks: "Feature image + detail links",
  IconLinks: "Icon Links",
  MediaTextOverlay: "Media + Text Overlay",
  DeliveryLifecycle: "Delivery Lifecycle",
} as const;
export const AccordionsFrontendComponent = {
  Accordion: "Accordion",
} as const;
export const TabsAndPillsFrontendComponent = {
  FeatureTabs: "Feature Tabs",
} as const;
export const ContentListsFrontendComponent = {
  MultiCardBulletsCTA: "Multi-card bullets + CTA",
} as const;
/* foundry:wiring:variants:end */

