// Generated by Foundry v3 wiring. Edit the wiring spec, then regenerate.
/** The same self-contained guard runs on the probe and in generated projects. */
export function assertCompleteCollections(value: unknown): void {
  if (!value || typeof value !== "object") return;
  if (Array.isArray(value)) {
    for (const item of value) assertCompleteCollections(item);
    return;
  }
  const object = value as Record<string, unknown>;
  if (object.json && typeof object.json === "object") {
    const references = new Set<string>();
    const collect = (node: unknown): void => {
      if (!node || typeof node !== "object") return;
      if (Array.isArray(node)) {
        node.forEach(collect);
        return;
      }
      const item = node as { sys?: { id?: string } };
      if (typeof item.sys?.id === "string") references.add(item.sys.id);
      Object.values(node).forEach(collect);
    };
    collect(object.links);
    const check = (node: unknown): void => {
      if (!node || typeof node !== "object") return;
      const item = node as {
        nodeType?: string;
        data?: { target?: { sys?: { id?: string } } };
        content?: unknown[];
      };
      const id = item.data?.target?.sys?.id;
      if (id && !references.has(id))
        throw new Error(
          "Rich text references require selected link sidecars or batched enrichment.",
        );
      item.content?.forEach(check);
    };
    check(object.json);
  }
  for (const [key, child] of Object.entries(value)) {
    if (key.endsWith("Collection") && child && typeof child === "object") {
      const collection = child as { total?: unknown; items?: unknown };
      if (
        typeof collection.total === "number" &&
        Array.isArray(collection.items) &&
        collection.total > collection.items.length
      )
        throw new Error(
          "Content collection exceeds its query limit; raise the limit or add batched enrichment.",
        );
    }
    assertCompleteCollections(child);
  }
}

