// Generated by Foundry v3 wiring. Edit the wiring spec, then regenerate.
/** Shared by the wiring probe and generated page data layer. No SDK dependency. */
export type ByIdQuery = {
  document: string;
  batchSize: number;
};
export type CollectionQueries = Record<
  string,
  {
    document: string;
    field: string;
    pageSize: number;
    byIds?: Record<string, ByIdQuery>;
    identityOnly?: string[];
  }
>;
type CollectionObject = Record<string, unknown>;
const asObject = (value: unknown): CollectionObject | undefined =>
  value && typeof value === "object" && !Array.isArray(value)
    ? (value as CollectionObject)
    : undefined;
/** Load shallow reference pages, group targets by type, then hydrate by sys.id.
 * The map merge preserves CMS ordering, repeated references and null slots.
 */
export async function resolveCollections(
  data: unknown,
  queries: CollectionQueries,
  query: (
    document: string,
    variables: Record<string, unknown>,
  ) => Promise<unknown>,
): Promise<void> {
  let requests = 0,
    itemCount = 0;
  const cache = new Map<string, CollectionObject>(),
    entries = new Map<string, CollectionObject>();
  const request = async (
    document: string,
    variables: Record<string, unknown>,
  ) => {
    if (++requests > 1000)
      throw new Error(
        "Page reference loading exceeds the safe request limit; no partial page was accepted.",
      );
    return asObject(await query(document, variables));
  };
  for (let pass = 0; pass < 32; pass++) {
    const pending = new Map<string, CollectionObject[]>();
    const scan = (value: unknown): void => {
      if (Array.isArray(value)) {
        value.forEach(scan);
        return;
      }
      const owner = asObject(value);
      if (!owner) return;
      for (const marker of Object.keys(queries))
        if (Object.hasOwn(owner, marker))
          pending.set(marker, [...(pending.get(marker) ?? []), owner]);
      for (const [key, child] of Object.entries(owner))
        if (key !== "json") scan(child);
    };
    scan(data);
    if (!pending.size) return;
    const touched = new Set<CollectionObject>();
    for (const [marker, owners] of pending) {
      const plan = queries[marker]!;
      const collections: CollectionObject[] = [];
      for (const owner of owners) {
        const id = asObject(owner.foundryCollectionOwner)?.id;
        if (typeof id !== "string")
          throw new Error(
            "A collection owner is missing its Contentful ID. Retry the page request.",
          );
        const key = JSON.stringify([marker, id]);
        let collection = cache.get(key);
        if (!collection) {
          let total: number | undefined;
          const items: unknown[] = [];
          do {
            const response = await request(plan.document, {
                id,
                skip: items.length,
              }),
              result = asObject(response?.foundryOwner),
              page = asObject(result?.[plan.field]);
            if (
              asObject(result?.sys)?.id !== id ||
              !page ||
              !Number.isSafeInteger(page.total) ||
              (page.total as number) < 0 ||
              !Array.isArray(page.items) ||
              page.skip !== items.length
            )
              throw new Error(
                "Contentful returned an invalid reference collection page.",
              );
            if (total !== undefined && total !== page.total)
              throw new Error(
                "Content changed during reference pagination. Retry the page request.",
              );
            total = page.total as number;
            if (total > 50000 || (itemCount += page.items.length) > 50000)
              throw new Error(
                "Page references exceed the safe item limit; no partial page was accepted.",
              );
            if (
              page.items.length > plan.pageSize ||
              items.length + page.items.length > total ||
              (!page.items.length && items.length < total)
            )
              throw new Error(
                "Reference pagination ended before all content was read.",
              );
            items.push(...page.items);
          } while (items.length < total);
          collection = { total, skip: 0, items };
          cache.set(key, collection);
        }
        collections.push(structuredClone(collection));
      }
      if (plan.byIds || plan.identityOnly?.length) {
        const idsByType = new Map<string, Set<string>>();
        for (const collection of collections)
          for (const value of collection.items as unknown[]) {
            if (value === null) continue;
            const item = asObject(value),
              id = asObject(item?.sys)?.id,
              type = item?.__typename;
            if (
              typeof id !== "string" ||
              typeof type !== "string" ||
              (!plan.byIds?.[type] && !plan.identityOnly?.includes(type))
            )
              throw new Error(
                "A shallow reference has an unsupported type or missing ID.",
              );
            if (plan.identityOnly?.includes(type)) continue;
            const ids = idsByType.get(type) ?? new Set<string>();
            ids.add(id);
            idsByType.set(type, ids);
          }
        for (const [type, allIds] of idsByType) {
          const fetcher = plan.byIds![type]!;
          const ids = [...allIds].filter(
            (id) => !entries.has(JSON.stringify([fetcher.document, id])),
          );
          for (let start = 0; start < ids.length; start += fetcher.batchSize) {
            const batch = ids.slice(start, start + fetcher.batchSize),
              response = await request(fetcher.document, { ids: batch }),
              result = asObject(response?.foundryEntries);
            if (
              !result ||
              result.total !== batch.length ||
              !Array.isArray(result.items) ||
              result.items.length !== batch.length
            )
              throw new Error(
                "A referenced entry could not be resolved by ID. Check published content and preview access.",
              );
            const seen = new Set<string>();
            for (const value of result.items) {
              const entry = asObject(value),
                id = asObject(entry?.sys)?.id;
              if (
                !entry ||
                typeof id !== "string" ||
                entry.__typename !== type ||
                !batch.includes(id) ||
                seen.has(id)
              )
                throw new Error(
                  "By-ID lookup returned duplicate, unexpected or invalid entries.",
                );
              seen.add(id);
              entries.set(JSON.stringify([fetcher.document, id]), entry);
            }
          }
        }
        for (const collection of collections)
          collection.items = (collection.items as unknown[]).map((value) => {
            if (value === null) return null;
            if (
              plan.identityOnly?.includes(asObject(value)?.__typename as string)
            )
              return value;
            const item = asObject(value)!,
              id = asObject(item.sys)!.id,
              fetcher = plan.byIds![item.__typename as string]!;
            return structuredClone(
              entries.get(JSON.stringify([fetcher.document, id]))!,
            );
          });
      }
      owners.forEach((owner, index) => {
        owner[plan.field] = collections[index];
        delete owner[marker];
        touched.add(owner);
      });
    }
    for (const owner of touched) delete owner.foundryCollectionOwner;
  }
  throw new Error(
    "Reference loading exceeds the supported depth or contains a cycle.",
  );
}

